// GatewaySnapshotConfig仅给出真实域数据回调；Runtime与排空由启动装配接公共屏障，缺项不冒安全。
func GatewaySnapshotConfig(store *gatewayruntime.Store,root string) lifecycle.SnapshotConfig{
 return lifecycle.SnapshotConfig{Owner:"model-gateway",DataRoot:root,Watermark:func(ctx context.Context)(int64,error){return GatewayWatermark(ctx,store.DB())},Capture:func(ctx context.Context,cut lifecycle.SnapshotSafeCut,workspace string,input lifecycle.SnapshotExportInput)(lifecycle.DomainSnapshotManifest,error){return CaptureGatewaySnapshot(ctx,store,root,cut,workspace,input)},MigrateStage:MigrateGatewayStage,ValidateStaged:ValidateGatewayStage,StageBudget:GatewayStageBudget}
}
func GatewayWatermark(ctx context.Context,db *sql.DB)(int64,error){var revision int64;if err:=db.QueryRowContext(ctx,`SELECT revision FROM gateway_snapshot_state WHERE singleton=1`).Scan(&revision);err!=nil{return 0,gatewayruntime.ExecutionStorageError(err)};if revision<1{return 0,platform.NewError(platform.CodeIntegrityError,false,"网关快照业务修订水位缺失")};return revision,nil}

// CaptureGatewaySnapshot只在公共safe cut后执行一致SQL备份，绝不复制live DB/WAL或control。
func CaptureGatewaySnapshot(ctx context.Context,store *gatewayruntime.Store,root string,cut lifecycle.SnapshotSafeCut,workspace string,input lifecycle.SnapshotExportInput)(lifecycle.DomainSnapshotManifest,error){
 var result lifecycle.DomainSnapshotManifest
 entries,err:=os.ReadDir(filepath.Join(root,"active"));if err!=nil{return result,gatewayruntime.ExecutionStorageError(err)};for _,entry:=range entries{if !slices.Contains([]string{"model-gateway.db","model-gateway.db-wal","model-gateway.db-shm"},entry.Name())||!entry.Type().IsRegular()||entry.IsDir(){return result,platform.NewError(platform.CodeIntegrityError,false,"网关active含未知权威文件，不能静默漏备份")}}
 var epoch string;if err=store.DB().QueryRowContext(ctx,`SELECT data_epoch FROM runtime_meta WHERE singleton=1`).Scan(&epoch);err!=nil{return result,gatewayruntime.ExecutionStorageError(err)};watermark,err:=GatewayWatermark(ctx,store.DB());if err!=nil{return result,err};if epoch!=cut.Epoch||epoch!=input.DataEpoch||watermark!=cut.Watermark||input.BarrierID!=cut.BarrierID{return result,platform.NewError(platform.CodeStaleResult,false,"网关安全截点与真实数据库代际/水位不同")}
 dir:=filepath.Join(workspace,"files");if err=os.MkdirAll(dir,0700);err!=nil{return result,gatewayruntime.ExecutionStorageError(err)};path:=filepath.Join(dir,"model-gateway.db");var pages,pageSize int64;if err=store.DB().QueryRowContext(ctx,`PRAGMA page_count`).Scan(&pages);err!=nil{return result,gatewayruntime.ExecutionStorageError(err)};if err=store.DB().QueryRowContext(ctx,`PRAGMA page_size`).Scan(&pageSize);err!=nil{return result,gatewayruntime.ExecutionStorageError(err)};if pages<1||pageSize<1||pages>lifecycle.MaxArchiveBytes/pageSize{return result,platform.NewError(platform.CodeBudgetExceeded,false,"网关SQL一致备份超过20GiB")};if err=lifecycle.CheckSnapshotDiskBudget(ctx,workspace,pages*pageSize*3);err!=nil{return result,err}
 if err=lifecycle.ValidatePrivatePath(path,"regular-file",true);err!=nil{return result,err};if _,err=store.DB().ExecContext(ctx,`VACUUM main INTO ?`,path);err!=nil{return result,gatewayruntime.ExecutionStorageError(err)}
 db,err:=OpenGatewaySnapshotDB(ctx,path,false);if err!=nil{return result,err};closed:=false;defer func(){if !closed{_ = db.Close()}}()
 if !input.IncludeSecrets{if err=RedactGatewaySnapshot(ctx,db,path);err!=nil{return result,err}}
 assets,invocations,err:=GatewaySnapshotInventory(ctx,db,epoch);if err!=nil{return result,err};if err=db.Close();err!=nil{return result,gatewayruntime.ExecutionStorageError(err)};closed=true;file,err:=GatewaySnapshotFile(ctx,path);if err!=nil{return result,err};file.Path="model-gateway.db"
 after,err:=GatewayWatermark(ctx,store.DB());if err!=nil{return result,err};if after!=watermark{return result,platform.NewError(platform.CodeStaleResult,false,"safe后发生业务写入，不能封存伪截点")}
 migrations,err:=gatewaymigrations.All();if err!=nil{return result,err}
 result=lifecycle.DomainSnapshotManifest{Format:"nice-wiki.domain-snapshot",SchemaVersion:2,Owner:"model-gateway",BackupID:input.BackupID,BarrierID:cut.BarrierID,SnapshotID:input.SnapshotID,SourceEpoch:epoch,DataSchemaVersion:len(migrations),RevisionWatermark:watermark,ContainsSecrets:input.IncludeSecrets,Files:[]lifecycle.DomainSnapshotFile{file},Objects:[]lifecycle.DomainSnapshotObject{},Publications:[]lifecycle.SnapshotPublishedRevisionRef{},References:[]lifecycle.DomainSnapshotReference{},Assets:[]platform.AssetVersionRef{},Invocations:invocations}
 for i:=range assets{asset:=assets[i];result.References=append(result.References,lifecycle.DomainSnapshotReference{Kind:"asset",Asset:&asset})};return result,nil
}

// GatewaySnapshotInventory从全部原调用材料穷尽真实付费调用和固定媒体引用；缺旧证据不能伪空。
func GatewaySnapshotInventory(ctx context.Context,db *sql.DB,epoch string)([]platform.AssetVersionRef,[]lifecycle.SnapshotInvocationRef,error){
 tx,err:=db.BeginTx(ctx,nil);if err!=nil{return nil,nil,gatewayruntime.ExecutionStorageError(err)};defer tx.Rollback();rows,err:=tx.QueryContext(ctx,`SELECT invocation_id FROM invocations ORDER BY invocation_id`);if err!=nil{return nil,nil,gatewayruntime.ExecutionStorageError(err)};type item struct{ID string};items:=[]item{};for rows.Next(){var item item;if err=rows.Scan(&item.ID);err!=nil{break};items=append(items,item);if len(items)>lifecycle.MaxArchiveFiles{err=platform.NewError(platform.CodeBudgetExceeded,false,"网关typed调用库存超过100000");break}};if err==nil{err=rows.Err()};_ = rows.Close();if err!=nil{return nil,nil,gatewayruntime.ExecutionStorageError(err)}
 assets:=map[string]platform.AssetVersionRef{};invocations:=[]lifecycle.SnapshotInvocationRef{};execution:=&gatewayruntime.ExecutionTransaction{Tx:tx,Context:ctx}
 for _,item:=range items{var op platform.OperationContext;var operationRaw []byte;if err=tx.QueryRowContext(ctx,`SELECT operation_json FROM invocations WHERE invocation_id=?`,item.ID).Scan(&operationRaw);err!=nil{return nil,nil,gatewayruntime.ExecutionStorageError(err)};if json.Unmarshal(operationRaw,&op)!=nil{return nil,nil,platform.NewError(platform.CodeIntegrityError,false,"快照原调用来源损坏")};projected,e:=gatewayruntime.IsRestoredEpoch(ctx,tx,op.DataEpoch,epoch);if e!=nil{return nil,nil,e};if !projected{return nil,nil,platform.NewError(platform.CodeIntegrityError,false,"快照原调用来源不属于当前认证namespace")};record,err:=gatewayruntime.ReadInvocationRecord(execution,op,item.ID);if err!=nil{return nil,nil,err};var route gatewayruntime.FixedRoute;if json.Unmarshal(record.Route,&route)!=nil{return nil,nil,platform.NewError(platform.CodeIntegrityError,false,"快照原冻结路线损坏")};invocations=append(invocations,lifecycle.SnapshotInvocationRef{InvocationID:item.ID,RootOperationID:record.Operation.RootOperationID,DataEpoch:record.Operation.DataEpoch})
  used:=map[string]bool{};for _,message:=range record.Request.Messages{if message.Parts==nil{continue};for _,part:=range *message.Parts{if part.Kind=="text"{continue};ref,err:=provider.MediaPartAsset(part);if err!=nil{return nil,nil,err};key:=provider.ImageKey(ref);version,ok:=route.AssetVersions[key];if !ok||version<1{return nil,nil,platform.NewError(platform.CodeDependencyUnavailable,false,"原付费资源缺accepted真实版本，不能猜版本或空库存")};used[key]=true;asset:=platform.AssetVersionRef{AssetID:ref.AssetId,Version:int64(version),SHA256:ref.Sha256,MediaType:ref.MediaType,ByteSize:int64(ref.ByteSize)};raw,_:=platform.CanonicalJSON(asset);assets[platform.HashBytes(raw)]=asset;if len(assets)>lifecycle.MaxArchiveFiles{return nil,nil,platform.NewError(platform.CodeBudgetExceeded,false,"真实资源引用库存超过100000")}}}
  if len(used)!=len(route.AssetVersions){return nil,nil,platform.NewError(platform.CodeIntegrityError,false,"原固定资源版本含未归属请求的记录")}
 }
 keys:=make([]string,0,len(assets));for key:=range assets{keys=append(keys,key)};slices.Sort(keys);result:=make([]platform.AssetVersionRef,0,len(keys));for _,key:=range keys{result=append(result,assets[key])};return result,invocations,nil
}

func OpenGatewaySnapshotDB(ctx context.Context,path string,readonly bool)(*sql.DB,error){
 if err:=lifecycle.ValidatePrivatePath(path,"regular-file",false);err!=nil{return nil,err};mode:="rw";if readonly{mode="ro"};dsn:=(&url.URL{Scheme:"file",Path:path}).String()+"?mode="+mode+"&_pragma=foreign_keys(ON)&_pragma=busy_timeout(2500)";db,err:=sql.Open("sqlite",dsn);if err!=nil{return nil,gatewayruntime.ExecutionStorageError(err)};db.SetMaxOpenConns(1);if err=db.PingContext(ctx);err!=nil{_ = db.Close();return nil,gatewayruntime.ExecutionStorageError(err)};if !readonly{if _,err=db.ExecContext(ctx,`PRAGMA journal_mode=DELETE`);err!=nil{_ = db.Close();return nil,gatewayruntime.ExecutionStorageError(err)}};return db,nil
}

func GatewaySnapshotFile(ctx context.Context,path string)(lifecycle.DomainSnapshotFile,error){
 if err:=lifecycle.ValidatePrivatePath(path,"regular-file",false);err!=nil{return lifecycle.DomainSnapshotFile{},err};file,err:=os.OpenFile(path,os.O_RDWR,0);if err!=nil{return lifecycle.DomainSnapshotFile{},gatewayruntime.ExecutionStorageError(err)};defer file.Close();digest:=sha256.New();buffer:=make([]byte,1<<20);var size int64
 for{if err=ctx.Err();err!=nil{return lifecycle.DomainSnapshotFile{},gatewayruntime.ExecutionStorageError(err)};n,e:=file.Read(buffer);size+=int64(n);if size>lifecycle.MaxArchiveBytes{return lifecycle.DomainSnapshotFile{},platform.NewError(platform.CodeBudgetExceeded,false,"网关数据库超过归档预算")};if n>0{_,_ = digest.Write(buffer[:n])};if e==io.EOF{break};if e!=nil{return lifecycle.DomainSnapshotFile{},gatewayruntime.ExecutionStorageError(e)}};if err=file.Sync();err!=nil{return lifecycle.DomainSnapshotFile{},gatewayruntime.ExecutionStorageError(err)};directory,err:=os.Open(filepath.Dir(path));if err!=nil{return lifecycle.DomainSnapshotFile{},gatewayruntime.ExecutionStorageError(err)};err=directory.Sync();_ = directory.Close();if err!=nil{return lifecycle.DomainSnapshotFile{},gatewayruntime.ExecutionStorageError(err)};return lifecycle.DomainSnapshotFile{SHA256:hex.EncodeToString(digest.Sum(nil)),ByteSize:size},nil
}

// RedactGatewaySnapshot仅改隔离副本，保留原版本/引用/费用/执行hash；VACUUM删除原加密material所在空闲页。
func RedactGatewaySnapshot(ctx context.Context,db *sql.DB,path string)error{
 source,err:=GatewaySnapshotFile(ctx,path);if err!=nil{return err};if _,err=db.ExecContext(ctx,`PRAGMA secure_delete=ON`);err!=nil{return gatewayruntime.ExecutionStorageError(err)};tx,err:=db.BeginTx(ctx,nil);if err!=nil{return gatewayruntime.ExecutionStorageError(err)};defer tx.Rollback()
 type material struct{Kind,Key string;Nonce,Ciphertext []byte};materials:=[]material{}
 for _,query:=range []string{`SELECT 'credential',provider_id||'|'||credential_version,nonce,ciphertext FROM credentials`,`SELECT 'header',ref_id,nonce,ciphertext FROM header_secrets`}{rows,e:=tx.QueryContext(ctx,query);if e!=nil{return gatewayruntime.ExecutionStorageError(e)};for rows.Next(){var m material;if err=rows.Scan(&m.Kind,&m.Key,&m.Nonce,&m.Ciphertext);err!=nil{break};materials=append(materials,m)};if err==nil{err=rows.Err()};_ = rows.Close();if err!=nil{return gatewayruntime.ExecutionStorageError(err)}}
 for _,m:=range materials{if len(m.Nonce)==0&&len(m.Ciphertext)==0{var valid bool;if err=tx.QueryRowContext(ctx,`SELECT EXISTS(SELECT 1 FROM snapshot_material_redactions WHERE kind=? AND record_key=? AND length(source_database_hash)=64 AND length(source_material_hash)=64)`,m.Kind,m.Key).Scan(&valid);err!=nil{return gatewayruntime.ExecutionStorageError(err)};if !valid{return platform.NewError(platform.CodeIntegrityError,false,"空密文缺原明确红action来源")};continue};if len(m.Nonce)!=12||len(m.Ciphertext)<=16{return platform.NewError(platform.CodeIntegrityError,false,"原加密material已损坏，不能当脱密正常值")};raw,_:=platform.CanonicalJSON(m);if _,err=tx.ExecContext(ctx,`INSERT INTO snapshot_material_redactions(kind,record_key,source_database_hash,source_material_hash) VALUES(?,?,?,?)`,m.Kind,m.Key,source.SHA256,platform.HashBytes(raw));err!=nil{return gatewayruntime.ExecutionStorageError(err)}}
 if _,err=tx.ExecContext(ctx,`UPDATE credentials SET nonce=X'',ciphertext=X''`);err!=nil{return gatewayruntime.ExecutionStorageError(err)};if _,err=tx.ExecContext(ctx,`UPDATE header_secrets SET nonce=X'',ciphertext=X''`);err!=nil{return gatewayruntime.ExecutionStorageError(err)};if err=tx.Commit();err!=nil{return gatewayruntime.ExecutionStorageError(err)};if _,err=db.ExecContext(ctx,`VACUUM`);err!=nil{return gatewayruntime.ExecutionStorageError(err)};return nil
}

func GatewayStageBudget(ctx context.Context,manifest lifecycle.DomainSnapshotManifest)(int64,error){
 if manifest.Owner!="model-gateway"||manifest.SchemaVersion!=2||len(manifest.Files)!=1||manifest.Files[0].Path!="model-gateway.db"||manifest.Assets==nil||manifest.Invocations==nil{return 0,platform.NewError(platform.CodeUnsupportedSchema,false,"网关仅接收有完整typed库存的V2独立SQL快照")};raw,err:=platform.CanonicalJSON(manifest);if err!=nil{return 0,err};size:=manifest.Files[0].ByteSize;extra:=int64(len(raw))*2+4<<20;if size<1||size>(lifecycle.MaxArchiveBytes-extra)/3{return 0,platform.NewError(platform.CodeBudgetExceeded,false,"网关暂存原库/事务journal/VACUUM和完整来源证明超过20GiB峰值预算")};return size*3+extra,nil
}

// MigrateGatewayStage只在公共完整认证source归档后写target配置/投影，不激活、不重写paid原scope/hash。
func MigrateGatewayStage(ctx context.Context,manifest lifecycle.DomainSnapshotManifest,target,root string)error{
 if _,err:=GatewayStageBudget(ctx,manifest);err!=nil{return err};path:=filepath.Join(root,"model-gateway.db");db,err:=OpenGatewaySnapshotDB(ctx,path,false);if err!=nil{return err};defer db.Close();if err=ValidateGatewayDatabase(ctx,db,manifest.SourceEpoch,manifest.DataSchemaVersion);err!=nil{return err};assets,invocations,err:=GatewaySnapshotInventory(ctx,db,manifest.SourceEpoch);if err!=nil{return err};expectedRefs:=[]lifecycle.DomainSnapshotReference{};for _,asset:=range assets{ref:=asset;expectedRefs=append(expectedRefs,lifecycle.DomainSnapshotReference{Kind:"asset",Asset:&ref})};actual,_:=platform.CanonicalJSON(struct{Invocations []lifecycle.SnapshotInvocationRef;References []lifecycle.DomainSnapshotReference}{invocations,expectedRefs});expected,_:=platform.CanonicalJSON(struct{Invocations []lifecycle.SnapshotInvocationRef;References []lifecycle.DomainSnapshotReference}{manifest.Invocations,manifest.References});if platform.HashBytes(actual)!=platform.HashBytes(expected)||len(manifest.Objects)!=0||len(manifest.Publications)!=0||len(manifest.Assets)!=0{return platform.NewError(platform.CodeIntegrityError,false,"网关源清单没有完整对应数据库真实typed库存")}
 if !manifest.ContainsSecrets{var secrets bool;if err=db.QueryRowContext(ctx,`SELECT EXISTS(SELECT 1 FROM credentials WHERE length(nonce)<>0 OR length(ciphertext)<>0) OR EXISTS(SELECT 1 FROM header_secrets WHERE length(nonce)<>0 OR length(ciphertext)<>0)`).Scan(&secrets);err!=nil{return gatewayruntime.ExecutionStorageError(err)};if secrets{return platform.NewError(platform.CodeIntegrityError,false,"不含secrets归档仍有真实加密material")}}
 tx,err:=db.BeginTx(ctx,nil);if err!=nil{return gatewayruntime.ExecutionStorageError(err)};defer tx.Rollback();raw,_:=platform.CanonicalJSON(manifest);hash:=platform.HashBytes(raw);if _,err=tx.ExecContext(ctx,`INSERT INTO restored_epoch_manifests(manifest_hash,manifest_json) VALUES(?,?) ON CONFLICT(manifest_hash) DO NOTHING`,hash,raw);err!=nil{return gatewayruntime.ExecutionStorageError(err)};epochs:=map[string]bool{manifest.SourceEpoch:true};for _,item:=range invocations{epochs[item.DataEpoch]=true};rows,e:=tx.QueryContext(ctx,`SELECT DISTINCT data_epoch FROM header_secrets UNION SELECT DISTINCT data_epoch FROM price_book_entries UNION SELECT source_epoch FROM restored_epoch_sources WHERE target_epoch=?`,manifest.SourceEpoch);if e!=nil{return gatewayruntime.ExecutionStorageError(e)};for rows.Next(){var source string;if e=rows.Scan(&source);e!=nil{break};epochs[source]=true};if e==nil{e=rows.Err()};_ = rows.Close();if e!=nil{return gatewayruntime.ExecutionStorageError(e)};for source:=range epochs{allowed,e:=gatewayruntime.IsRestoredEpoch(ctx,tx,source,manifest.SourceEpoch);if e!=nil{return e};if !allowed{return platform.NewError(platform.CodeIntegrityError,false,"源库含未认证历史代际材料")};binding,_:=platform.CanonicalJSON([]string{source,target,hash});if _,err=tx.ExecContext(ctx,`INSERT INTO restored_epoch_sources(source_epoch,target_epoch,manifest_hash,proof_hash) VALUES(?,?,?,?) ON CONFLICT(source_epoch,target_epoch) DO UPDATE SET manifest_hash=excluded.manifest_hash,proof_hash=excluded.proof_hash`,source,target,hash,platform.HashBytes(binding));err!=nil{return gatewayruntime.ExecutionStorageError(err)}}
 // 只迁移当前可编辑配置。原invocations/price/fee/attempt/route引用/证据/回执字节保留。
 for _,table:=range []string{"providers","models","profiles","task_assignments","fee_budget_policy","model_catalog_downloads","model_catalog_bindings","credentials"}{if _,err=tx.ExecContext(ctx,`UPDATE `+table+` SET data_epoch=? WHERE data_epoch=?`,target,manifest.SourceEpoch);err!=nil{return gatewayruntime.ExecutionStorageError(err)}}
 if _,err=tx.ExecContext(ctx,`UPDATE runtime_meta SET data_epoch=?,updated_at=? WHERE singleton=1`,target,platform.Now());err!=nil{return gatewayruntime.ExecutionStorageError(err)};if _,err=tx.ExecContext(ctx,`INSERT INTO invocation_lookup_tracking(singleton,format_version,data_epoch,proof_kind,proof_hash,created_at) VALUES(1,1,?,'verified_restore',?,?) ON CONFLICT(singleton) DO UPDATE SET data_epoch=excluded.data_epoch,proof_kind=excluded.proof_kind,proof_hash=excluded.proof_hash,created_at=excluded.created_at`,target,hash,platform.Now());err!=nil{return gatewayruntime.ExecutionStorageError(err)};if err=tx.Commit();err!=nil{return gatewayruntime.ExecutionStorageError(err)};if _,err=db.ExecContext(ctx,`PRAGMA wal_checkpoint(TRUNCATE)`);err!=nil{return gatewayruntime.ExecutionStorageError(err)};return nil
}

func ValidateGatewayStage(ctx context.Context,manifest lifecycle.DomainSnapshotManifest,target,root string)error{
 if _,err:=GatewayStageBudget(ctx,manifest);err!=nil{return err};db,err:=OpenGatewaySnapshotDB(ctx,filepath.Join(root,"model-gateway.db"),true);if err!=nil{return err};defer db.Close();if err=ValidateGatewayDatabase(ctx,db,target,manifest.DataSchemaVersion);err!=nil{return err};raw,_:=platform.CanonicalJSON(manifest);var hash,kind,epoch string;if err=db.QueryRowContext(ctx,`SELECT proof_hash,proof_kind,data_epoch FROM invocation_lookup_tracking WHERE singleton=1`).Scan(&hash,&kind,&epoch);err!=nil{return gatewayruntime.ExecutionStorageError(err)};if hash!=platform.HashBytes(raw)||kind!="verified_restore"||epoch!=target{return platform.NewError(platform.CodeIntegrityError,false,"目标完整tracking不绑定本次认证源清单")};_,invocations,err:=GatewaySnapshotInventory(ctx,db,target);if err!=nil{return err};actual,_:=platform.CanonicalJSON(invocations);expected,_:=platform.CanonicalJSON(manifest.Invocations);if platform.HashBytes(actual)!=platform.HashBytes(expected){return platform.NewError(platform.CodeIntegrityError,false,"目标投影改写或遗漏原付费调用库存")};return nil
}

func ValidateGatewayDatabase(ctx context.Context,db *sql.DB,epoch string,schema int)error{
 migrations,err:=gatewaymigrations.All();if err!=nil{return err};if schema!=len(migrations){return platform.NewError(platform.CodeUnsupportedSchema,false,"网关快照schema需当前完整版本，不猜旧格式迁移")};var current string;var version,count int;if err=db.QueryRowContext(ctx,`SELECT data_epoch FROM runtime_meta WHERE singleton=1`).Scan(&current);err!=nil{return gatewayruntime.ExecutionStorageError(err)};if current!=epoch{return platform.NewError(platform.CodeIntegrityError,false,"快照库真实代际不匹配")};if err=db.QueryRowContext(ctx,`SELECT coalesce(max(version),0),count(*) FROM schema_migrations`).Scan(&version,&count);err!=nil{return gatewayruntime.ExecutionStorageError(err)};if version!=schema||count!=schema{return platform.NewError(platform.CodeUnsupportedSchema,false,"快照迁移记录不完整")};for _,migration:=range migrations{var name string;if err=db.QueryRowContext(ctx,`SELECT name FROM schema_migrations WHERE version=?`,migration.Version).Scan(&name);err!=nil{return gatewayruntime.ExecutionStorageError(err)};if name!=migration.Name{return platform.NewError(platform.CodeUnsupportedSchema,false,"快照迁移名称与实际当前schema不同")}};var check string;if err=db.QueryRowContext(ctx,`PRAGMA quick_check(1)`).Scan(&check);err!=nil{return gatewayruntime.ExecutionStorageError(err)};if check!="ok"{return platform.NewError(platform.CodeIntegrityError,false,"快照SQL完整性失败")};rows,err:=db.QueryContext(ctx,`PRAGMA foreign_key_check`);if err!=nil{return gatewayruntime.ExecutionStorageError(err)};bad:=rows.Next();err=rows.Err();_ = rows.Close();if err!=nil{return gatewayruntime.ExecutionStorageError(err)};if bad{return platform.NewError(platform.CodeIntegrityError,false,"快照费用/引用权威关系缺失")};return nil
}
